import os

for root, dirs, files in os.walk('unpacked'):
    for f in sorted(files):
        p = os.path.join(root, f)
        print(p, os.path.getsize(p))

import sys

sys.path.insert(0, '.codex/skills/docx')

from scripts.utilities import XMLEditor

HEADLINES = [
    "EXECUTIVE SUMMARY",
    "FINANCIAL HIGHLIGHTS",
    "REVENUE BREAKDOWN BY SEGMENT",
    "KEY PERFORMANCE INDICATORS",
    "OPERATING EXPENSES",
    "Q1 2025 OUTLOOK",
    "RISK FACTORS",
]

editor = XMLEditor('verify_unpacked/word/document.xml')

ok = True
total_underlined = 0

for headline in HEADLINES:
    node = editor.get_node(tag='w:p', contains=headline)
    underlined = 0
    for r in node.getElementsByTagName('w:r'):
        rpr = None
        for child in r.childNodes:
            if child.nodeType == child.ELEMENT_NODE and child.tagName == 'w:rPr':
                rpr = child
                break
        if rpr is not None:
            for u in rpr.getElementsByTagName('w:u'):
                if u.getAttribute('w:val') == 'single':
                    underlined += 1
    total_underlined += underlined
    status = 'OK' if underlined >= 1 else 'MISSING'
    if underlined < 1:
        ok = False
    print(f"{status}: {headline} -> underlined runs: {underlined}")

# Count underlined runs outside headline paragraphs
all_runs = editor.dom.getElementsByTagName('w:r')
headline_paras = set()
for h in HEADLINES:
    headline_paras.add(id(editor.get_node(tag='w:p', contains=h)))

outside = 0
for r in all_runs:
    if id(r) not in {id(rr) for p in [] for rr in []}:
        # check if run's ancestor paragraph is a headline paragraph
        anc = r.parentNode
        is_headline = False
        while anc is not None:
            if anc.nodeType == anc.ELEMENT_NODE and anc.tagName == 'w:p' and id(anc) in headline_paras:
                is_headline = True
                break
            anc = anc.parentNode
        if not is_headline:
            rpr = None
            for child in r.childNodes:
                if child.nodeType == child.ELEMENT_NODE and child.tagName == 'w:rPr':
                    rpr = child
                    break
            if rpr is not None and rpr.getElementsByTagName('w:u'):
                outside += 1

print('total underlined runs in headlines:', total_underlined)
print('underlined runs outside headlines:', outside)
if not ok or total_underlined != 7 or outside != 0:
    sys.exit(1)
print('VERIFICATION PASSED')

